import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Alert, Button } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ===================== STYLE (ปรับให้สวยและรองรับมือถือ) ===================== */
const themeStyle = `
.chart-scroll { overflow-x: auto; overflow-y: hidden; -webkit-overflow-scrolling: touch; }
.history-header {
  background: linear-gradient(135deg, #5e72e4 0%, #825ee4 100%) !important;
  border-radius: 12px 12px 0 0 !important;
  padding: 1.5rem !important;
  border: none !important;
}
.history-header .card-title { 
  color: white !important; 
  margin: 0 !important; 
  font-weight: 700; 
  font-size: 1.2rem; 
  letter-spacing: 0.5px;
}
.card {
  border: none !important;
  box-shadow: 0 10px 30px rgba(0,0,0,0.08) !important;
  margin-bottom: 25px !important;
  border-radius: 12px !important;
  overflow: hidden;
}
.form-select, .form-control {
  border-radius: 10px !important;
  padding: 10px 15px !important;
  border: 1px solid #e0e6ed !important;
  font-size: 0.95rem !important;
  transition: all 0.2s;
}
.form-select:focus { border-color: #5e72e4; box-shadow: 0 0 0 3px rgba(94, 114, 228, 0.1); }
.form-label {
  font-weight: 600;
  color: #32325d;
  font-size: 0.85rem;
  margin-bottom: 0.5rem;
}
.ct-bar { cursor: pointer; transition: opacity 0.3s; }
.ct-bar:hover { opacity: 0.85; }
.legend-container {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  background: #f8f9fe;
  padding: 12px;
  border-radius: 10px;
}
.legend-item { display: flex; align-items: center; gap: 6px; font-size: 0.8rem; font-weight: 600; color: #525f7f; }
.legend-dot { width: 10px; height: 10px; border-radius: 50%; }

/* Mobile Adjustments */
@media (max-width: 768px) {
  .history-header { padding: 1rem !important; }
  .history-header .card-title { font-size: 1rem; }
  .d-flex.gap-2 { flex-direction: column; gap: 8px !important; }
  .legend-container { justify-content: flex-start; }
}
`;

const CAMERA_MAP = { CAM01: "วิศวะ", CAM02: "วิทยาศาสตร์", CAM03: "ศิลปศาสตร์", CAM04: "PKY" };

function History() {
  const currentYearBE = new Date().getFullYear() + 543;
  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, "0"));
  const [selectedYearBE, setSelectedYearBE] = useState(currentYearBE.toString());
  const [cameraId, setCameraId] = useState("CAM01");
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");

  const [rawFileData, setRawFileData] = useState({ labels: [], series: [[]] });
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });
  const [detailChart, setDetailChart] = useState(null); 
  const [selectedHour, setSelectedHour] = useState(null);
  const [isLoaded, setIsLoaded] = useState(false);

  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" }, { val: "03", name: "มีนาคม" },
    { val: "04", name: "เมษายน" }, { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" }, { val: "09", name: "กันยายน" },
    { val: "10", name: "ตุลาคม" }, { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" },
  ];

  const timeOptions = Array.from({ length: 16 }, (_, i) => {
    const hour = (i + 7).toString().padStart(2, "0") + ":00";
    return <option key={hour} value={hour}>{hour}</option>;
  });

  const handleSearch = async () => {
    setIsLoaded(false);
    setDetailChart(null);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, "0")}`;
    
    try {
      const res = await fetch(`http://localhost:3001/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`);
      const result = await res.json();

      if (result && result.labels && result.labels.length > 0) {
        setRawFileData(result);
        const bucket = {};
        result.labels.forEach((label, idx) => {
          const hour = label.split(":")[0].padStart(2, '0') + ":00";
          if (!bucket[hour]) bucket[hour] = { sum: 0, count: 0 };
          bucket[hour].sum += result.series[0][idx];
          bucket[hour].count += 1;
        });

        const labels = [], series = [];
        const startH = parseInt(startTime.split(":")[0]);
        const endH = parseInt(endTime.split(":")[0]);

        for (let i = startH; i <= endH; i++) {
          const h = i.toString().padStart(2, '0') + ":00";
          labels.push(h);
          series.push(bucket[h] ? Math.round(bucket[h].sum / bucket[h].count) : 0);
        }
        setChartState({ labels, series: [series] });
      } else {
        setChartState({ labels: [], series: [[]] });
        setRawFileData({ labels: [], series: [[]] });
      }
    } catch (err) { 
        console.error("Fetch error:", err);
        setChartState({ labels: [], series: [[]] });
    } finally { setIsLoaded(true); }
  };

  useEffect(() => { handleSearch(); }, [selectedDay, selectedMonth, selectedYearBE, cameraId, startTime, endTime]);

  const getDensityColor = (val) => {
    if (val >= 41) return "#f5365c"; 
    if (val >= 31) return "#fb6340"; 
    if (val >= 21) return "#ffd600"; 
    return "#2dce89"; 
  };

  const chartEvents = {
    draw: (data) => {
      if (data.type === "bar") {
        data.element.attr({ style: `stroke: ${getDensityColor(data.value.y)}; stroke-width: 25px;` });
        data.group.elem("text", { 
          x: data.x2, y: data.y2 - 12, 
          style: "font-size:11px; font-weight:700; text-anchor:middle; fill:#525f7f;" 
        }).text(data.value.y);
      }
    },
    created: (context) => {
      if (!context.svg) return;
      context.svg._node.onclick = (e) => {
        const bar = e.target.closest('.ct-bar');
        if (!bar) return;
        const allBars = Array.from(bar.parentNode.querySelectorAll('.ct-bar'));
        const index = allBars.indexOf(bar);
        if (index !== -1 && chartState.labels[index]) {
          const hourLabel = chartState.labels[index];
          const dLabels = [], dSeries = [];
          rawFileData.labels.forEach((l, i) => {
            if (l.startsWith(hourLabel.split(":")[0])) {
              dLabels.push(l);
              dSeries.push(rawFileData.series[0][i]);
            }
          });
          setSelectedHour(hourLabel);
          setDetailChart({ labels: dLabels, series: [dSeries] });
        }
      };
    }
  };

  return (
    <Container fluid className="py-4 bg-light min-vh-100">
      <style>{themeStyle}</style>
      
      {/* ส่วนค้นหา */}
      <Row className="justify-content-center">
        <Col lg="10" xl="11">
          <Card>
            <Card.Header className="history-header">
              <Card.Title as="h4">📅 สถิติปริมาณคนย้อนหลัง</Card.Title>
            </Card.Header>
            <Card.Body className="p-4">
              <Row className="g-4">
                <Col md="4">
                  <Form.Label className="form-label">สถานที่</Form.Label>
                  <Form.Select value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                    {Object.entries(CAMERA_MAP).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
                  </Form.Select>
                </Col>
                <Col md="4">
                  <Form.Label className="form-label">วันที่</Form.Label>
                  <div className="d-flex gap-2">
                    <Form.Select value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)}>{Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}</Form.Select>
                    <Form.Select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}>{monthsThai.map(m=><option key={m.val} value={m.val}>{m.name}</option>)}</Form.Select>
                    <Form.Select value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)}><option value={currentYearBE}>{currentYearBE}</option><option value={currentYearBE-1}>{currentYearBE-1}</option></Form.Select>
                  </div>
                </Col>
                <Col md="4">
                  <Form.Label className="form-label">ช่วงเวลา</Form.Label>
                  <div className="d-flex align-items-center gap-2">
                    <Form.Select value={startTime} onChange={(e) => setStartTime(e.target.value)}>{timeOptions}</Form.Select>
                    <span className="text-muted small fw-bold">ถึง</span>
                    <Form.Select value={endTime} onChange={(e) => setEndTime(e.target.value)}>{timeOptions}</Form.Select>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* ส่วนกราฟ */}
      {isLoaded && chartState.labels.length > 0 ? (
        <Row className="justify-content-center">
          <Col lg="10" xl="11">
            <Card>
              <Card.Body className="p-4">
                <div className="d-flex justify-content-between align-items-center mb-4 flex-wrap gap-3">
                  <h5 className="mb-0 text-dark fw-bold">📊 รายชั่วโมง: {CAMERA_MAP[cameraId]}</h5>
                  <div className="legend-container">
                    <div className="legend-item"><span className="legend-dot" style={{background:'#2dce89'}}></span> 0-20</div>
                    <div className="legend-item"><span className="legend-dot" style={{background:'#ffd600'}}></span> 21-30</div>
                    <div className="legend-item"><span className="legend-dot" style={{background:'#fb6340'}}></span> 31-40</div>
                    <div className="legend-item"><span className="legend-dot" style={{background:'#f5365c'}}></span> 41+</div>
                  </div>
                </div>
                <div className="chart-scroll">
                  <div style={{ width: "100%", minWidth: "850px", height: "380px" }}>
                    <ChartistGraph data={chartState} type="Bar" options={{ low: 0, fullWidth: true, chartPadding: { top: 30, right: 20 } }} listener={chartEvents} />
                  </div>
                </div>
                <div className="text-center mt-3">
                  <small className="text-muted bg-light px-3 py-1 rounded-pill">💡 จิ้มที่แท่งกราฟเพื่อดูรายละเอียดรายนาที</small>
                </div>
              </Card.Body>
            </Card>

            {/* กราฟรายละเอียด */}
            {detailChart && (
              <Card className="mt-4 border-0 shadow-lg">
                <Card.Header className="bg-white border-0 py-3 d-flex justify-content-between align-items-center">
                  <h6 className="mb-0 fw-bold text-primary">🔍 รายละเอียดรายนาที ช่วงเวลา {selectedHour} น.</h6>
                  <Button variant="link" className="text-danger p-0" onClick={() => setDetailChart(null)}>ปิดหน้าต่างนี้</Button>
                </Card.Header>
                <Card.Body className="pt-0">
                  <div className="chart-scroll">
                    <div style={{ width: "100%", minWidth: "1100px", height: "320px" }}>
                      <ChartistGraph data={detailChart} type="Line" options={{ low: 0, showArea: true, fullWidth: true, axisX: { labelInterpolationFnc: (v, i) => i % 5 === 0 ? v : null, offset: 50 } }} />
                    </div>
                  </div>
                </Card.Body>
              </Card>
            )}
          </Col>
        </Row>
      ) : (
        isLoaded && (
          <Row className="justify-content-center">
            <Col lg="10" xl="11">
              <Card className="no-data-card py-5 text-center">
                <Card.Body>
                  <div className="mb-3 display-4">📂</div>
                  <h4 className="text-muted fw-bold">ยังไม่มีข้อมูลสถิติในวันที่เลือก</h4>
                  <p className="text-muted mb-4 small">ลองตรวจสอบช่วงเวลาหรือเลือกวันใหม่</p>
                  <Alert variant="warning" className="d-inline-block px-4 rounded-pill border-0 shadow-sm">
                    {selectedDay} {monthsThai.find(m => m.val === selectedMonth)?.name} {selectedYearBE} ({startTime} - {endTime})
                  </Alert>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        )
      )}
    </Container>
  );
}

export default History;
